/** Msg defines the Msg service. */
export interface Msg {
  /**
   * UpdateParams defines a (governance) operation for updating the module
   * parameters. The authority defaults to the x/gov module account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /**
   * AddElectoralAuthority authorizes an address to create elections.
   * Authority-gated (governance).
   */
  AddElectoralAuthority(request: MsgAddElectoralAuthority): Promise<MsgAddElectoralAuthorityResponse>;
  /**
   * RemoveElectoralAuthority revokes an address's authorization to create
   * new elections. Does not affect elections it already created.
   */
  RemoveElectoralAuthority(request: MsgRemoveElectoralAuthority): Promise<MsgRemoveElectoralAuthorityResponse>;
  /**
   * CreateElection defines a new election. Only callable by a currently
   * authorized electoral authority.
   */
  CreateElection(request: MsgCreateElection): Promise<MsgCreateElectionResponse>;
  /**
   * RegisterToVote registers the caller as an eligible voter for an
   * election, during its registration window, provided they hold an
   * ACTIVE credential of the election's eligibility_credential_type from a
   * currently authorized issuer.
   */
  RegisterToVote(request: MsgRegisterToVote): Promise<MsgRegisterToVoteResponse>;
  /**
   * CommitVote submits a voter's hidden vote commitment during the voting
   * window. One commitment per voter per election, enforced by nullifier.
   */
  CommitVote(request: MsgCommitVote): Promise<MsgCommitVoteResponse>;
  /**
   * RevealVote reveals a previously committed vote during the reveal
   * window; it's only counted in ElectionResults if the revealed
   * (choice, salt) hashes to the stored commitment.
   */
  RevealVote(request: MsgRevealVote): Promise<MsgRevealVoteResponse>;
}

